  const dashboardMarkup=()=>`<div class="result-dashboard"><div class="dash-top"><div><small>DATA INSIGHT · 2026</small><h3>新能源汽车跨境增长看板</h3><p>目标市场综合经营洞察</p></div><img src="/assets/agent-ip.png" alt="智能助手 IP"></div><div class="dash-kpis"><div><span>目标市场规模</span><b>€ 8.42B</b><em>↑ 18.6%</em></div><div><span>潜在用户</span><b>2.38M</b><em>↑ 12.4%</em></div><div><span>平均转化率</span><b>6.84%</b><em>↑ 2.1%</em></div><div><span>机会指数</span><b>86</b><em>高潜力</em></div></div><div class="dash-panels"><section><div class="dash-title"><b>市场增长趋势</b><span>近 6 个月</span></div><div class="dash-chart"><i style="height:38%"></i><i style="height:49%"></i><i style="height:43%"></i><i style="height:66%"></i><i style="height:75%"></i><i style="height:91%"></i></div><div class="dash-labels"><span>3月</span><span>4月</span><span>5月</span><span>6月</span><span>7月</span><span>8月</span></div></section><section><div class="dash-title"><b>目标用户画像</b><span>核心人群</span></div><div class="profile-row"><i>42%</i><div><b>品质进阶型家庭</b><span>30–44 岁 · SUV 偏好 · 重视安全</span></div></div><div class="profile-row"><i>31%</i><div><b>都市科技先锋</b><span>25–34 岁 · 智能化偏好 · 社媒活跃</span></div></div><div class="profile-row"><i>27%</i><div><b>绿色生活践行者</b><span>关注续航、环保与使用成本</span></div></div></section></div><div class="dash-insight"><b>AI 核心洞察</b><p>优先聚焦中高端纯电 SUV，以安全、智能座舱与全生命周期成本作为沟通主线；德国、荷兰和挪威为第一阶段重点市场。</p></div></div>`;
